 1	import { useState } from "react";
 2	import { IconLoader2, IconFolderOpen } from "@tabler/icons-react";
 3	import { Button } from "@/components/ui/button";
 4	import { ConsiliumLogo } from "./ConsiliumLogo";
 5	import { bridge } from "@/services";
 6	import { useSettingsStore } from "@/stores";
 7	import { toast } from "@/components/ui/sonner";
 8	
 9	interface Props {
10	  onSetupComplete: () => void;
11	}
12	
13	export function ProjectSetupScreen({ onSetupComplete }: Props) {
14	  const [initializing, setInitializing] = useState(false);
15	
16	  const handleInitialize = async () => {
17	    setInitializing(true);
18	    try {
19	      const result = await bridge.initializeProject();
20	      if (result.success) {
21	        toast.success("Project initialized");
22	        onSetupComplete();
23	      } else {
24	        toast.error(result.error || "Failed to initialize project");
25	      }
26	    } catch (err) {
27	      toast.error(err instanceof Error ? err.message : "Failed to initialize project");
28	    } finally {
29	      setInitializing(false);
30	    }
31	  };
32	
33	  const handleSkip = () => {
34	    useSettingsStore.setState({ projectSetupSkipped: true });
35	    onSetupComplete();
36	  };
37	
38	  return (
39	    <div className="h-full flex items-center justify-center p-6">
40	      <div className="max-w-sm text-center space-y-6">
41	        <ConsiliumLogo className="h-40 mx-auto opacity-50" />
42	        <div className="space-y-2">
43	          <div className="inline-flex items-center gap-2 text-amber-500">
44	            <IconFolderOpen className="size-5" />
45	            <span className="text-sm font-medium">Project Setup</span>
46	          </div>
47	          <p className="text-xs text-muted-foreground/70">
48	            This workspace hasn't been initialized for Consilium yet.
49	            Set up the project structure for sessions and agents to get started.
50	          </p>
51	        </div>
52	        <div className="flex flex-col gap-2">
53	          <Button onClick={handleInitialize} disabled={initializing} className="gap-2">
54	            {initializing ? (
55	              <>
56	                <IconLoader2 className="size-4 animate-spin" />
57	                Initializing...
58	              </>
59	            ) : (
60	              <>
61	                <IconFolderOpen className="size-4" />
62	                Initialize Project
63	              </>
64	            )}
65	          </Button>
66	          <Button onClick={handleSkip} variant="ghost" size="sm" className="text-muted-foreground">
67	            Skip
68	          </Button>
69	        </div>
70	      </div>
71	    </div>
72	  );
73	}
